import { DitherShader } from "@/components/ui/dither-shader";

export default function() {
  return (
    <DitherShader
      src="https://images.unsplash.com/photo-1555952517-2e8e729e0b44?q=80&w=1364&auto=format&fit=crop&ixlib=rb-4.1.0"
      gridSize={4}                // 网格密度，越小越细腻（1-8）
      ditherMode="bayer"          // bayer | halftone | noise | crosshatch
      colorMode="duotone"         // original | grayscale | duotone | custom
      primaryColor="#1e3a5f"      // 暗色
      secondaryColor="#f0e68c"    // 亮色
      threshold={0.45}            // 阈值 0-1
      animated={false}            // 开启噪点/半调动画
      className="h-72 w-[400px]"
    />
  );
}

